+    private static Properties loadProperties(Path indexPath) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(indexPath.toFile())) {
+            result.load(inputStream);
+            return result;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
