+    private IntegrityResult inspect(Properties properties, Path folderPath, Path indexPath) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String fileName = properties.getProperty(description);
+            Entry entry = new Entry(description, fileName);
+            if (deterministicFileNames) {
