    private static class DescriptionRuleViolationFileNameStrategy implements RuleViolationFileNameStrategy {
        @Override
        public String createRuleFileName(String ruleDescription) {
            Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(ruleDescription);
            String keptWord = null;
            while (matcher.find()) {
                keptWord = matcher.group();
            }
            String hash = sha256(ruleDescription);
            return (keptWord == null ? "rule" : keptWord) + "-" + hash;
        }

        private static String sha256(String text) {
            try {
                byte[] digest = MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));
                StringBuilder result = new StringBuilder(digest.length * 2);
                for (byte value : digest) {
                    result.append(String.format("%02x", value & 0xff));
                }
                return result.toString();
            } catch (NoSuchAlgorithmException e) {
                throw new IllegalStateException(e);
            }
        }
    }

