/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 * <br><br>
 * The individual violation file names can be selected with {@code default.fileNames}. The accepted built-in values are
 * {@code random} (the default) and {@code description}; any other value is interpreted as a fully-qualified
 * {@link RuleViolationFileNameStrategy} implementation.
 * <br><br>
 * The index can be checked while initializing with {@code default.integrity=repair} or
 * {@code default.integrity=fail}. The default, {@code ignore}, does not inspect the stored entries or the folder.
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_RANDOM = "random";
    private static final String FILE_NAMES_DESCRIPTION = "description";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_IGNORE = "ignore";
    private static final String INTEGRITY_REPAIR = "repair";
    private static final String INTEGRITY_FAIL = "fail";

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])[A-Za-z0-9]{4,120}(?![A-Za-z0-9])");
    private static final Pattern ONLY_LINE_BREAKS_PATTERN = Pattern.compile("[\\r\\n]*");
    private static final String ACCEPTED_INTEGRITY_VALUES = "repair, fail and ignore";

    /* The value object is also the lock. This makes all stores in this JVM observe the same index transaction. */
    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();
    private static final ConcurrentHashMap<String, Object> STORE_CREATION_LOCKS = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean customConstructorStrategy;

    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private boolean deterministicFileNames;
    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private IntegrityMode integrityMode;
    private File storeFolder;
    private Path storeFolderPath;
    private Path realStoreFolderPath;
    private Path storedRulesPath;
    private Path realStoredRulesPath;
    private FileSyncedProperties storedRules;

    /**
     * Creates a standard store that names new violation files by random UUIDs.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
        customConstructorStrategy = false;
    }

    /**
     * Creates a store with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        constructorStrategy = checkNotNull(ruleViolationFileNameStrategy);
        customConstructorStrategy = true;
    }

    @Override
    public void initialize(Properties properties) {
        Properties configuration = properties == null ? new Properties() : properties;
        storeCreationAllowed = Boolean.parseBoolean(configuration.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(configuration.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(configuration.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE));
        configureFileNameStrategy(configuration);

        String path = configuration.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
        storeFolder = new File(path);
        storedRulesPath = storeFolder.toPath().resolve(STORED_RULES_FILE_NAME);
        String storeKey = canonicalPath(storedRulesPath.toFile());
        Object creationLock = STORE_CREATION_LOCKS.computeIfAbsent(storeKey, ignored -> new Object());

        synchronized (creationLock) {
            initializeAt(storeKey);
        }
    }

    private void configureFileNameStrategy(Properties properties) {
        if (customConstructorStrategy) {
            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
                        FILE_NAMES_PROPERTY_NAME));
            }
            ruleViolationFileNameStrategy = constructorStrategy;
            deterministicFileNames = true;
            return;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
        if (FILE_NAMES_RANDOM.equals(configured)) {
            ruleViolationFileNameStrategy = description -> UUID.randomUUID().toString();
            deterministicFileNames = false;
        } else if (FILE_NAMES_DESCRIPTION.equals(configured)) {
            ruleViolationFileNameStrategy = new DescriptionRuleViolationFileNameStrategy();
            deterministicFileNames = true;
        } else {
            ruleViolationFileNameStrategy = instantiateStrategy(configured);
            deterministicFileNames = true;
        }
    }

    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
        try {
            Class<?> strategyType = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
            }
            Constructor<?> constructor = strategyType.getConstructor();
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
                 InvocationTargetException | ClassCastException | IllegalArgumentException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured by %s=%s; the value must be random, description, or the fully-qualified name of a RuleViolationFileNameStrategy with a public no-argument constructor",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
        }
    }

    private void initializeAt(String storeKey) {
        Path folderPath = storeFolderPath = storeFolder.toPath().toAbsolutePath().normalize();
        Path indexPath = storedRulesPath = folderPath.resolve(STORED_RULES_FILE_NAME);
        boolean indexExists = Files.exists(indexPath, LinkOption.NOFOLLOW_LINKS);

        if (!indexExists && !storeCreationAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
        }

        if (indexExists && !isDirectRegularFile(indexPath, folderPath)) {
            throw new StoreInitializationFailedException(String.format(
                    "The stored rules index %s must be a regular file directly in the store folder",
                    indexPath.toAbsolutePath()));
        }

        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s.%s=true",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        ensureStoreFolder(folderPath);
        try {
            realStoreFolderPath = folderPath.toRealPath();
            realStoredRulesPath = realStoreFolderPath.resolve(STORED_RULES_FILE_NAME);
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }

        FileSyncedProperties rules = STORED_RULES_BY_PATH.get(storeKey);
        if (rules != null) {
            synchronized (rules) {
                initializeExistingIndex(rules, indexExists, folderPath, indexPath);
            }
        } else {
            /* A fail-mode check of an absent index must happen before creating that index. */
            Properties rulesToCheck = indexExists ? loadProperties(indexPath) : new Properties();
            Properties rulesBeforeRepair = copyOf(rulesToCheck);
            if (integrityMode != IntegrityMode.IGNORE) {
                IntegrityResult integrity = inspect(rulesToCheck, folderPath, indexPath);
                if (integrityMode == IntegrityMode.FAIL && integrity.hasProblems()) {
                    throw integrity.failure(indexPath);
                }
                if (integrityMode == IntegrityMode.REPAIR) {
                    repair(rulesToCheck, integrity);
                }
            }
            if (!indexExists) {
                createIndex(indexPath);
            }
            rules = new FileSyncedProperties(indexPath, rulesBeforeRepair);
            replacePropertiesDuringInitialization(rules, rulesToCheck);
            STORED_RULES_BY_PATH.put(storeKey, rules);
        }

        storedRules = rules;
    }

    private void initializeExistingIndex(FileSyncedProperties rules, boolean indexExists, Path folderPath, Path indexPath) {
        Properties loaded = indexExists ? loadProperties(indexPath) : new Properties();
        if (integrityMode != IntegrityMode.IGNORE) {
            IntegrityResult integrity = inspect(loaded, folderPath, indexPath);
            if (integrityMode == IntegrityMode.FAIL && integrity.hasProblems()) {
            if (integrityMode == IntegrityMode.FAIL && integrity.hasProblems()) {
                throw integrity.failure(indexPath);
            }
            if (integrityMode == IntegrityMode.REPAIR) {
                repair(loaded, integrity);
            }
        }
        if (!indexExists) {
            createIndex(indexPath);
        }
        replacePropertiesDuringInitialization(rules, loaded);
    }

    private void replacePropertiesDuringInitialization(FileSyncedProperties rules, Properties properties) {
        try {
            rules.replaceLoadedProperties(properties);
        } catch (StoreUpdateFailedException e) {
            throw new StoreInitializationFailedException("Could not repair the stored rules index", e);
        }
    }

    private void ensureStoreFolder(Path folderPath) {
        try {
            if (!Files.exists(folderPath, LinkOption.NOFOLLOW_LINKS)) {
                Files.createDirectories(folderPath);
            }
            if (!Files.isDirectory(folderPath, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException(String.format("Store path %s is not a directory", folderPath));
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void createIndex(Path indexPath) {
        try {
            if (!Files.exists(indexPath, LinkOption.NOFOLLOW_LINKS)) {
                Files.createFile(indexPath);
            }
            if (!isDirectRegularFile(indexPath, storeFolderPath)) {
                throw new StoreInitializationFailedException(String.format(
                        "The stored rules index %s must be a regular file directly in the store folder", indexPath.toAbsolutePath()));
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static String canonicalPath(File file) {
        try {
            return file.getCanonicalPath();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static boolean isDirectRegularFile(Path path, Path folderPath) {
        return path.getParent() != null && path.getParent().equals(folderPath)
                && Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS);
    }

    private static Properties loadProperties(Path indexPath) {
        Properties result = new Properties();
        try (FileInputStream inputStream = new FileInputStream(indexPath.toFile())) {
            result.load(inputStream);
            return result;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static Properties copyOf(Properties source) {
        Properties result = new Properties();
        result.putAll(source);
        return result;
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storedRules) {
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        checkNotNull(rule);
        checkNotNull(violations);
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storedRules) {
            String description = ensureUnixLineBreaks(rule.getDescription());
            String existingFileName = storedRules.getProperty(description);
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && existingFileName != null) {
                forgetRule(description, existingFileName);
                return;
            }

            if (existingFileName != null) {
                saveKnownRule(description, existingFileName, violations);
            } else if (!violations.isEmpty() || integrityMode != IntegrityMode.REPAIR) {
                saveNewRule(description, violations);
            }
        }
    }

    private void saveKnownRule(String description, String fileName, List<String> violations) {
        ResolvedFile file = resolveFile(fileName);
        if (!file.usable() || isIndex(file.realPath)) {
            throw rejectedSave("the existing entry does not name a regular file directly in the store folder", description);
        }
        writeViolations(file.realPath, violations);
    }

    private void saveNewRule(String description, List<String> violations) {
        String fileName = createFileName(description);
        Path destination = directPathOrNull(fileName);
        if (destination == null || isIndex(destination) || entryRecords(fileName) || exists(destination)) {
            throw rejectedSave(String.format("the file name '%s' is unsafe or already owned", fileName), description);
        }

        Path temporary = null;
        boolean destinationCreated = false;
        try {
            temporary = writeTemporary(violations);
            moveWithoutReplacement(temporary, destination);
            temporary = null;
            destinationCreated = true;

            Properties updated = storedRules.copy();
            updated.setProperty(description, fileName);
            storedRules.replaceLoadedProperties(updated);
        } catch (IOException e) {
            deleteQuietly(temporary);
            if (destinationCreated) {
                deleteQuietly(destination);
            }
            throw new StoreUpdateFailedException(e);
        } catch (RuntimeException e) {
            deleteQuietly(temporary);
            if (destinationCreated) {
                deleteQuietly(destination);
            }
            throw e;
        }
    }

    private void forgetRule(String description, String fileName) {
        ResolvedFile file = resolveFile(fileName);
        Path directPath = directPathOrNull(fileName);
        if (STORED_RULES_FILE_NAME.equals(fileName) || (directPath != null && exists(directPath) && !file.usable())) {
            throw rejectedSave("the existing entry does not name a deletable file in the store folder", description);
        }
        boolean shared = file.usable() && isSharedWithAnotherEntry(description, file);
        if (file.usable() && !shared) {
            if (isIndex(file.realPath) || !isInsideStore(file.realPath)) {
                throw rejectedSave("the existing entry does not name a deletable file in the store folder", description);
            }
            try {
                Files.delete(file.realPath);
                if (file.symbolicLink) {
                    Files.delete(file.lexicalPath);
                }
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }

        Properties updated = storedRules.copy();
        updated.remove(description);
        storedRules.replaceLoadedProperties(updated);
    }

    private boolean isSharedWithAnotherEntry(String description, ResolvedFile file) {
        for (String otherDescription : storedRules.stringPropertyNames()) {
            if (!description.equals(otherDescription)) {
                String otherName = storedRules.getProperty(otherDescription);
                ResolvedFile otherFile = resolveFile(otherName);
                if (file.usable() && otherFile.usable() && file.realPath.equals(otherFile.realPath)) {
                    return true;
                }
            }
        }
        return false;
    }

    private String createFileName(String description) {
        String fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
        if (fileName == null || fileName.trim().isEmpty()) {
            throw rejectedSave("the configured RuleViolationFileNameStrategy returned no file name", description);
        }
        return fileName;
    }

    private StoreUpdateFailedException rejectedSave(String reason, String description) {
        return new StoreUpdateFailedException(String.format("Cannot store violations for rule '%s': %s", description, reason));
    }

    private void writeViolations(Path destination, List<String> violations) {
        Path temporary = null;
        try {
            temporary = writeTemporary(violations);
            moveReplacing(temporary, destination);
        } catch (IOException e) {
            deleteQuietly(temporary);
            throw new StoreUpdateFailedException(e);
        }
    }

    private Path writeTemporary(List<String> violations) throws IOException {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        Path temporary = Files.createTempFile(storeFolderPath, ".violation-", ".tmp");
        try {
            Files.write(temporary, builder.toString().getBytes(StandardCharsets.UTF_8));
            return temporary;
        } catch (IOException e) {
            deleteQuietly(temporary);
            throw e;
        }
    }

    private void moveWithoutReplacement(Path source, Path destination) throws IOException {
        try {
            Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE);
        } catch (AtomicMoveNotSupportedException e) {
            Files.move(source, destination);
        }
    }

    private void moveReplacing(Path source, Path destination) throws IOException {
        try {
            Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (AtomicMoveNotSupportedException e) {
            Files.move(source, destination, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private void deleteQuietly(Path path) {
        if (path != null) {
            try {
                Files.deleteIfExists(path);
            } catch (IOException ignored) {
                log.debug("Could not clean up temporary store file {}", path);
            }
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storedRules) {
            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            ResolvedFile file = resolveFile(ruleDetailsFileName);
            if (!file.usable()) {
                throw new StoreReadException(new IOException("Stored rule file is not a regular file directly in the store folder"));
            }
            List<String> result = readLines(file.realPath);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

