    private ResolvedFile resolveFile(String fileName) {
        if (fileName == null) {
            return ResolvedFile.broken(null);
        }
        try {
            Path lexicalPath = storeFolderPath.resolve(fileName).normalize();
            if (fileName.isEmpty() || lexicalPath.getParent() == null || !lexicalPath.getParent().equals(storeFolderPath)) {
                return ResolvedFile.broken(lexicalPath);
            }
            if (!Files.exists(lexicalPath, LinkOption.NOFOLLOW_LINKS)) {
                return ResolvedFile.broken(lexicalPath);
            }
            Path realPath = lexicalPath.toRealPath();
            boolean regularFile = Files.isRegularFile(realPath, LinkOption.NOFOLLOW_LINKS);
            boolean usable = isInsideStore(realPath) && regularFile && !isIndex(realPath);
            return new ResolvedFile(lexicalPath, regularFile ? realPath : null, Files.isSymbolicLink(lexicalPath), usable);
        } catch (IOException | InvalidPathException e) {
            return ResolvedFile.broken(null);
        }
    }

    private Path directPathOrNull(String fileName) {
        if (fileName == null || fileName.trim().isEmpty()) {
            return null;
        }
        try {
            Path path = storeFolderPath.resolve(fileName).normalize();
            if (path.getParent() == null || !path.getParent().equals(storeFolderPath) || isIndex(path)) {
                return null;
            }
            return path;
        } catch (InvalidPathException e) {
            return null;
        }
    }

    private boolean isInsideStore(Path path) {
        return path != null && path.getParent() != null && path.getParent().equals(realStoreFolderPath);
    }

    private boolean isIndex(Path path) {
        return path != null && (path.equals(storedRulesPath) || path.equals(realStoredRulesPath));
    }

    private boolean exists(Path path) {
        return Files.exists(path, LinkOption.NOFOLLOW_LINKS);
    }

    private boolean entryRecords(String fileName) {
        for (String description : storedRules.stringPropertyNames()) {
            if (fileName.equals(storedRules.getProperty(description))) {
                return true;
            }
        }
        return false;
    }

    private IntegrityResult inspect(Properties properties, Path folderPath, Path indexPath) {
        List<Entry> entries = new ArrayList<>();
        for (String description : properties.stringPropertyNames()) {
            String fileName = properties.getProperty(description);
            Entry entry = new Entry(description, fileName);
            if (deterministicFileNames) {
                entry.derivedName = createFileNameForInspection(description);
            } else {
                entry.derivedName = fileName;
            }
            entry.file = resolveFile(fileName);
            if (entry.file.broken) {
                entry.broken = true;
            } else {
                entry.resolved = readLines(entry.file.realPath).isEmpty();
            }
            entries.add(entry);
        }

        markShared(entries);
        markCollisions(entries);
        for (Entry entry : entries) {
            entry.misplaced = !safeEquals(entry.fileName, entry.derivedName);
            if (entry.misplaced) {
                Path derivedPath = directPathOrNull(entry.derivedName);
                entry.occupied = derivedPath == null || exists(derivedPath) || recordedByAnother(properties, entry.description, entry.derivedName);
            }
        }

        List<String> unownedFiles = findUnownedFiles(entries, folderPath, indexPath);
        return new IntegrityResult(entries, unownedFiles);
    }

    private String createFileNameForInspection(String description) {
        String fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
        if (fileName == null || fileName.trim().isEmpty()) {
            throw new StoreInitializationFailedException(String.format(
                    "The configured RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
        }
        return fileName;
    }

